curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" --data-urlencode 'token=<TOKEN>' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print(d); sys.exit()
for u in d['members']:
    name=u.get('profile',{}).get('real_name') or ''
    disp=u.get('profile',{}).get('display_name') or ''
    if 'diego' in (name+disp).lower() or 'alvarez' in (name+disp).lower():
        print(u['id'], '|', name, '|', disp)
"

